import { test, expect } from '@playwright/test';

test.describe('Multi-step Form Navigation - Go Back', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/multi-step-form');
  });

  test('should navigate back to previous step without losing form data', async ({ page }) => {
    // Step 1: Enter name
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('John Doe');

    // Step 2: Enter email
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('john@example.com');

    // Step 3: Enter phone
    const phoneInput = page.getByLabel('Phone Number');
    await phoneInput.fill('555-123');

    // Verify current step is 3
    const stepIndicator = page.getByRole('status', { name: /Step 3/i });
    await expect(stepIndicator).toBeVisible();

    // Click back button to go to Step 2
    const backButton = page.getByRole('button', { name: /Back/i });
    await backButton.click();

    // Verify current step is 2
    const stepIndicator2 = page.getByRole('status', { name: /Step 2/i });
    await expect(stepIndicator2).toBeVisible();

    // Verify name and email data are preserved
    await expect(nameInput).toHaveValue('John Doe');
    await expect(emailInput).toHaveValue('john@example.com');

    // Click back button again to go to Step 1
    await backButton.click();

    // Verify current step is 1
    const stepIndicator1 = page.getByRole('status', { name: /Step 1/i });
    await expect(stepIndicator1).toBeVisible();

    // Verify name data is preserved
    await expect(nameInput).toHaveValue('John Doe');

    // Verify email and phone fields are cleared (as expected in Step 1)
    await expect(emailInput).toHaveValue('');
    await expect(phoneInput).toHaveValue('');
  });

  test('should handle navigation back when form data is incomplete', async ({ page }) => {
    // Step 1: Enter name
    const nameInput = page.getByLabel('Full Name');
    await nameInput.fill('Jane Smith');

    // Step 2: Enter email
    const emailInput = page.getByLabel('Email Address');
    await emailInput.fill('jane@example.com');

    // Step 3: Attempt to navigate back without filling phone
    const backButton = page.getByRole('button', { name: /Back/i });
    await backButton.click();

    // Verify current step is 2
    const stepIndicator2 = page.getByRole('status', { name: /Step 2/i });
    await expect(stepIndicator2).toBeVisible();

    // Verify name and email data are preserved
    await expect(nameInput).toHaveValue('Jane Smith');
    await expect(emailInput).toHaveValue('jane@example.com');

    // Verify phone field is empty
    await expect(phoneInput).toHaveValue('');

    // Click back button again to go to Step 1
    await backButton.click();

    // Verify current step is 1
    const stepIndicator1 = page.getByRole('status', { name: /Step 1/i });
    await expect(stepIndicator1).toBeVisible();

    // Verify name data is preserved
    await expect(nameInput).toHaveValue('Jane Smith');

    // Verify email and phone fields are cleared
    await expect(emailInput).toHaveValue('');
    await expect(phoneInput).toHaveValue('');
  });
});
